import React, { useRef, useEffect, useState } from 'react';
import * as faceapi from 'face-api.js';
import { Link } from 'react-router-dom';
import mqtt from 'mqtt';
export default function LoginView() {
  const videoRef = useRef();
  const [message, setMessage] = useState('');
  const loginUserId = sessionStorage.getItem('loginUserId');
  const [status, setStatus] = useState('');
  const [modelsLoaded, setModelsLoaded] = useState(false);

  useEffect(() => {
    const loadModels = async () => {
      await faceapi.nets.ssdMobilenetv1.loadFromUri('/models');
      await faceapi.nets.faceRecognitionNet.loadFromUri('/models');
      await faceapi.nets.faceLandmark68Net.loadFromUri('/models');
      setModelsLoaded(true);
    };
    loadModels();
  }, []);
  const sendMessage = () => {

    const mqthost = localStorage.getItem('mqthost') ;
    const mqtusername = localStorage.getItem('mqtusername') ;
    const mqtpassword = localStorage.getItem('mqtpassword') ;

    const client = mqtt.connect(mqthost, {
      username: mqtusername,
      password: mqtpassword,
      protocol: 'wss'
    });

    client.on('connect', () => {
      setStatus('Connected to MQTT broker');
      client.publish('esp/test/receive', 'open', {}, (err) => {
        if (err) {
          setStatus('Failed to send message');
          console.error('Failed to send message:', err);

        } else {

          console.log('Message sent successfully:');
        }
        client.end();
      });
    });

    client.on('error', (err) => {
      console.error('Connection error:', err);
      setStatus('MQTT connection error');
      client.end();
    });
  };
  const startCamera = () => {
    navigator.mediaDevices.getUserMedia({ video: {} })
      .then(stream => {
        videoRef.current.srcObject = stream;
      });
  };

  const login = async () => {
    if (!modelsLoaded) {
      return alert('⏳ Please wait, models are still loading...');
    }
    const detection = await faceapi
    .detectSingleFace(videoRef.current, new faceapi.SsdMobilenetv1Options())
    .withFaceLandmarks()
    .withFaceDescriptor();
  
    if (!detection || !detection.detection?.box || detection.detection.box.top === null || detection.detection.box.bottom === null) {
      return alert('⚠️ Face detection failed, please try again with better lighting or position.');
    }
    const inputDescriptor = detection.descriptor;
    const users = JSON.parse(localStorage.getItem('faceUsers') || '[]');

    const matchedUser = users.find(user => {
      const storedDescriptor = new Float32Array(user.faceId);
      const distance = faceapi.euclideanDistance(inputDescriptor, storedDescriptor);
      return distance < 0.6;
    });

    if (!matchedUser) {
      setMessage('Face not recognized');
    } else if (matchedUser.userId === loginUserId) {
      setMessage(`Login OK — Bienvenido ${matchedUser.userId}`);
      sendMessage();
    } else {
      setMessage('Face does not belong to the entered user ID');
    }
  };
  return (
    <div className="p-4">
    <h1 className="text-xl font-bold">Face Login</h1>
    <p className="mb-2">Logging in as User ID: <strong>{loginUserId}</strong></p>
 
    <video ref={videoRef} autoPlay muted width="320" height="240" className="my-2" />
    <button onClick={startCamera} className="btn btn-warning px-4 py-2 mr-2">Start Camera</button>
    <button onClick={login} className="btn btn-secondary px-4 py-2">Login</button>
    <p className="mt-2 text-lg">{message}</p>
    {!modelsLoaded && (
<p className="text-red-500 mb-2">⏳ Loading models, please wait...</p>
)}
  </div>
  );
}
