import React, { useState } from 'react';
import { Link } from 'react-router-dom';

export default function SettingsView() {
  const [mqthost, setMqthost] = useState('');
  const [mqtusername, setMqtusername] = useState('');
  const [mqtpassword, setMqtpassword] = useState('');

  const registerData = () => {
    localStorage.setItem('mqthost', mqthost);
    localStorage.setItem('mqtusername', mqtusername);
    localStorage.setItem('mqtpassword', mqtpassword);
    alert("Data saved to localStorage!");
  };

  return (
    <div className="p-4">
      <h2 className="text-xl font-bold mb-4">MQTT Settings</h2>

      <div className="mb-2">
        <label className="block mb-1">MQTT Host</label>
        <input
          type="text"
          className="border p-2 w-full"
          value={mqthost}
          onChange={(e) => setMqthost(e.target.value)}
        />
      </div>

      <div className="mb-2">
        <label className="block mb-1">Username</label>
        <input
          type="text"
          className="border p-2 w-full"
          value={mqtusername}
          onChange={(e) => setMqtusername(e.target.value)}
        />
      </div>

      <div className="mb-4">
        <label className="block mb-1">Password</label>
        <input
          type="password"
          className="border p-2 w-full"
          value={mqtpassword}
          onChange={(e) => setMqtpassword(e.target.value)}
        />
      </div>

      <button
        onClick={registerData}
        className="btn btn-warning px-4 py-2 mr-2"
      >
        Save
      </button>

      
    </div>
  );
}
