
import * as tf from "@tensorflow/tfjs";
import Session from "react-session-api";

import React, { useRef, useEffect, useState } from 'react';
import * as faceapi from 'face-api.js';
import { Link } from 'react-router-dom';
import LoginView from './LoginView';
import RegisterView from './RegisterView';
import UserListView from './UserListView';
import SettingsView from './SettingsView';


const App = () => {


 

  const [activeTab, setActiveTab] = useState("registrar");

  const renderTabContent = () => {
    switch (activeTab) {
      case "registrar":
        return <RegisterView/>;
      case "ver":
        return <UserListView/>;
      case "config":
        return <SettingsView/>;
        case "login":
          return <LoginView/>;
      default:
        return null;
    }
  };

  return (
    <div className="p-4">
      <div className="flex space-x-4 mb-4">
        <button
          onClick={() => setActiveTab("registrar")}
          className={`px-4 py-2 rounded ${activeTab === "registrar" ? "bg-blue-500 text-white" : "bg-gray-200"}`}
        >
          Registrar Usuario
        </button>
        <button
          onClick={() => setActiveTab("ver")}
          className={`px-4 py-2 rounded ${activeTab === "ver" ? "bg-blue-500 text-white" : "bg-gray-200"}`}
        >
          Ver Usuarios
        </button>
        <button
          onClick={() => setActiveTab("config")}
          className={`px-4 py-2 rounded ${activeTab === "config" ? "bg-blue-500 text-white" : "bg-gray-200"}`}
        >
          Configuración
        </button>
        <button
          onClick={() => setActiveTab("login")}
          className={`px-4 py-2 rounded ${activeTab === "login" ? "bg-blue-500 text-white" : "bg-gray-200"}`}
        >
          Login
        </button>
      </div>

      <div className="border p-4 rounded shadow">
        {renderTabContent()}
      </div>
    </div>
  );
};

export default App;