import React from 'react';
import { Link } from 'react-router-dom';

export default function UserListView() {
  const users = JSON.parse(localStorage.getItem('faceUsers') || '[]');
  const clearUsers = () => {
    localStorage.removeItem('faceUsers');
    alert('All users cleared');
  };
  return (
    <div className="p-4">
      <h1 className="text-xl font-bold"> Usuarios Registrados</h1>
      <table className="border-collapse border border-gray-400 mt-4">
        <thead>
          <tr>
            <th className="border border-gray-300 px-4 py-2">User ID</th>
            <th className="border border-gray-300 px-4 py-2">Registrado en</th>
          </tr>
        </thead>
        <tbody>
          {users.map((user, index) => (
            <tr key={index}>
              <td className="border border-gray-300 px-4 py-2">{user.userId}</td>
              <td className="border border-gray-300 px-4 py-2">{user.registeredAt}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <button onClick={clearUsers} className="btn btn-warning px-4 py-2 my-2 py-2 my-2 ml-2">Limpiar Usuarios</button>
    
    </div>
  );
}
